CREATE TABLE IF NOT EXISTS mag_quotes (
  id SERIAL PRIMARY KEY,
  text TEXT NOT NULL,
  author VARCHAR(200) NOT NULL,
  author_role VARCHAR(300) NOT NULL DEFAULT '',
  source VARCHAR(300) NOT NULL DEFAULT '',
  comment TEXT NOT NULL DEFAULT '',
  show_date DATE UNIQUE,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS mag_quote_days (
  day DATE PRIMARY KEY,
  quote_id INT NOT NULL REFERENCES mag_quotes(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS mag_quote_days_q_idx ON mag_quote_days (quote_id);

