INSERT INTO mag_quotes (text, author, author_role, source, comment) VALUES
('Существует лишь одно верное определение цели бизнеса — создание клиента.', 'Питер Друкер', 'теоретик менеджмента', 'книга «Практика менеджмента», 1954', 'Выручка, маржа и рост — следствия. Если клиентов становится меньше, никакая оптимизация затрат этого не исправит.'),
('Нет ничего более бесполезного, чем с большой эффективностью делать то, чего не следует делать вовсе.', 'Питер Друкер', 'теоретик менеджмента', 'Harvard Business Review, 1963', 'Перед тем как ускорять процесс, проверьте, нужен ли он. Самая дешёвая автоматизация — отказ от лишней операции.'),
('Будьте осторожны, когда другие жадничают, и жадничайте, когда другие боятся.', 'Уоррен Баффетт', 'инвестор, Berkshire Hathaway', 'письмо акционерам, 1986', 'Лучшие условия по сделкам и аренде обычно бывают тогда, когда рынок в панике, а не на пике оптимизма.'),
('Только когда начинается отлив, становится видно, кто купался без плавок.', 'Уоррен Баффетт', 'инвестор, Berkshire Hathaway', 'письмо акционерам, 2001', 'Высокая ставка — тот самый отлив: долговая нагрузка, незаметная в хорошие годы, становится главным риском.'),
('Цена — это то, что вы платите. Ценность — это то, что вы получаете.', 'Уоррен Баффетт', 'инвестор, Berkshire Hathaway', 'письмо акционерам, 2008 (со ссылкой на Бенджамина Грэма)', 'Дешёвый подрядчик, сервис или сотрудник может обойтись дороже — считайте полную стоимость владения.'),
('Риск возникает тогда, когда вы не знаете, что делаете.', 'Уоррен Баффетт', 'инвестор, Berkshire Hathaway', 'из выступлений', 'Прежде чем вкладываться в новую нишу, посчитайте её экономику на цифрах, а не на впечатлениях.'),
('Покажите мне стимулы, и я покажу вам результат.', 'Чарли Мангер', 'инвестор, вице-председатель Berkshire Hathaway', 'из выступлений', 'Система мотивации важнее регламентов: люди делают то, за что им платят, а не то, что написано в инструкции.'),
('Знайте, чем вы владеете, и знайте, почему вы этим владеете.', 'Питер Линч', 'управляющий фондом Fidelity Magellan', 'из книг и выступлений', 'Правило одинаково для акций, недвижимости и доли в чужом бизнесе.'),
('Помни, что время — деньги.', 'Бенджамин Франклин', 'политик, издатель, учёный', '«Совет молодому торговцу», 1748', 'Час собственника — самый дорогой ресурс компании. Посчитайте, сколько он стоит, прежде чем тратить его на рутину.'),
('Не от благожелательности мясника, пивовара или булочника ожидаем мы получить свой обед, а от соблюдения ими своих собственных интересов.', 'Адам Смит', 'экономист', '«Исследование о природе и причинах богатства народов», 1776', 'Лучшие партнёрства строятся на понятной выгоде для обеих сторон, а не на доброй воле.'),
('В долгосрочной перспективе мы все мертвы.', 'Джон Мейнард Кейнс', 'экономист', '«Трактат о денежной реформе», 1923', 'Ждать, что рынок «когда-нибудь сам выправится», — тоже решение, и у него есть цена.'),
('Бизнес, который не производит ничего, кроме денег, — бедный бизнес.', 'Генри Форд', 'основатель Ford Motor Company', 'из интервью', 'Прибыль — показатель того, что вы делаете что-то полезное для клиентов, а не сама цель.'),
('Выживают только параноики.', 'Эндрю Гроув', 'генеральный директор Intel', 'название книги, 1996', 'Следите за точками перелома: новая технология или регулирование может обнулить устойчивую модель за пару лет.'),
('Ваша маржа — это моя возможность.', 'Джефф Безос', 'основатель Amazon', 'из интервью', 'Высокая наценка без защиты от конкурентов привлекает тех, кто готов зарабатывать меньше на каждом клиенте.'),
('Если вам не стыдно за первую версию продукта, значит, вы запустились слишком поздно.', 'Рид Хоффман', 'сооснователь LinkedIn', 'из выступлений', 'Первую версию проверяют на реальных покупателях, а не на совещаниях.'),
('Делайте то, что нужно людям.', 'Пол Грэм', 'сооснователь Y Combinator', 'девиз Y Combinator', 'Самая частая причина закрытия нового направления — не нехватка денег, а отсутствие спроса.'),
('Оставайтесь голодными. Оставайтесь безрассудными.', 'Стив Джобс', 'сооснователь Apple', 'речь в Стэнфорде, 2005 (цитата из Whole Earth Catalog)', ''),
('Не потому, что дела трудны, мы не дерзаем; они трудны потому, что мы не дерзаем.', 'Сенека', 'философ', '«Нравственные письма к Луцилию», письмо 104', ''),
('Путь в тысячу ли начинается с первого шага.', 'Лао-цзы', 'философ', '«Дао дэ цзин», глава 64', 'Большой проект — это серия небольших решений. Определите первое и сделайте его сегодня.'),
('Краткость — сестра таланта.', 'Антон Чехов', 'писатель', 'письмо Александру Чехову, 1889', 'Касается писем клиентам, коммерческих предложений и отчётов для руководства.');